          "玻璃上出现哈气画的爱心。",
          "林维试探性地问：‘老婆，是你吗？’"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "第3章：同居守则",
        "core_event": "林维接受了苏雅的存在，制定了‘人鬼同居’的规则。",
        "emotional_tone": "温馨、治愈、轻快",
        "key_scenes": [
          "林维对着空气介绍基地设施。",
          "制定规则：每天早安吻（亲空气），吃饭多摆一副碗筷。",
          "苏雅通过敲击摩斯密码回应：‘我想吃草莓’。"
        ]
      }
    ],
    "turning_point": "林维不再害怕，而是把‘闹鬼’当成了甜蜜的负担，决定为了苏雅扩建温室种草莓。"
  },
  "act_two": {
    "description": "展开火星种田的甜蜜日常，通过‘规则怪谈’式的互动加深感情，并引入危机。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "第4章：幽灵的口味",
        "core_event": "第一批草莓成熟，苏雅‘偷吃’（草莓干瘪消失），林维宠溺地种更多。",
        "emotional_tone": "甜蜜、轻松、种田爽感",
        "key_scenes": [
          "林维发现草莓少了，空气中弥漫着甜味。",
          "苏雅用番茄酱在桌上画笑脸。",
          "林维一边吐槽一边扩建种植槽。"
        ]
      },
      {
        "chapter_number": 5,
        "chapter_title": "第5章：沙尘暴里的拥抱",
        "core_event": "火星沙尘暴来袭，温室玻璃破裂，苏雅显灵保护了林维和土豆。",
        "emotional_tone": "紧张 -> 感动 -> 震撼",
        "key_scenes": [
          "警报大作，林维抢修温室。",
          "一块碎片飞向林维，被看不见的屏障挡住。",
          "林维感觉到一个冰凉的怀抱紧紧抱住自己。"
        ]
      },
      {
        "chapter_number": 6,
        "chapter_title": "第6章：疯狂的计划",
        "core_event": "林维决定利用基地的3D生物打印机，为苏雅制造一个实体身体。",
        "emotional_tone": "坚定、热血、充满希望",
        "key_scenes": [
          "林维查阅资料，修改打印机程序。",
          "苏雅敲击‘不要冒险’，林维坚持‘我想抱抱你’。",
          "开始收集材料，拆卸废弃舱段。"
        ]
      },
      {
        "chapter_number": 7,
        "chapter_title": "第7章：寻找生物凝胶",
        "core_event": "林维冒险前往坠毁的补给舱寻找关键材料，苏雅一路护送。",
        "emotional_tone": "冒险、刺激、默契",
        "key_scenes": [
          "火星表面的艰难跋涉。",
          "苏雅帮忙侦测地形，避开流沙。",
          "成功拿到生物凝胶，两人在星空下‘牵手’回家。"
        ]
      }
    ],
    "turning_point": "材料收集齐全，打印程序就绪，但发现能源不足以支撑全过程。"
  },
  "act_three": {
    "description": "高潮冲突，在生存与爱情之间做出选择，最终迎来HE结局。",
    "key_chapters": [
      {
        "chapter_number": 8,
        "chapter_title": "第8章：能源危机",
        "core_event": "打印需要消耗基地80%的能源，意味着维生系统将停摆一小时，林维面临缺氧风险。",
        "emotional_tone": "焦灼、决绝",
        "key_scenes": [
          "AI警告能源不足。",
          "苏雅疯狂敲击‘停止’，试图破坏打印机。",
          "林维锁死权限：‘一小时而已，我憋得住。’"
        ]
      },
      {
        "chapter_number": 9,
        "chapter_title": "第9章：窒息的等待",
        "core_event": "打印开始，维生系统关闭，林维在寒冷和缺氧中等待苏雅重生。",
        "emotional_tone": "痛苦、深情、极致浪漫",
        "key_scenes": [
          "温度骤降，林维意识模糊。",
          "看着打印舱里逐渐成形的人影。",
          "幻觉中看到苏雅向他走来。"
        ]
      },
      {
        "chapter_number": 10,
        "chapter_title": "第10章：久违的触碰",
        "core_event": "苏雅实体化成功，在林维昏迷前唤醒了他，并重启了系统。",
        "emotional_tone": "感动、高潮、圆满",
        "key_scenes": [
          "温暖的手抚摸林维的脸。",
          "苏雅的第一句话：‘笨蛋。’",
          "系统重启，灯光亮起，两人相拥而泣。"
        ]
      },
      {
        "chapter_number": 11,
        "chapter_title": "第11章：火星伊甸园",
        "core_event": "尾声，两人在火星过上了没羞没臊的种田生活。",
        "emotional_tone": "宁静、幸福、余韵",
        "key_scenes": [
          "苏雅穿着林维的衬衫吃草莓。",
          "两人一起看着地球方向（或者就在火星看日落）。",
          "林维：‘地球毁灭了也没关系，这里就是家。’"
        ]
      }
    ]
  }
